MEETINGS = []

def add(identifier, title, people, intro, topics, ending):
    MEETINGS.append(dict(id=identifier, title=title, people=people, intro=intro, topics=topics, ending=ending))

def rows(text):
    result=[]
    for line in text.strip().splitlines():
        fields=[x.strip() for x in line.split('|')]
        assert len(fields)==10, (len(fields),line)
        result.append(dict(zip(['title','owner','deadline','fact','a','b','risk','check','decision','open'],fields)))
    return result

def build(m):
    parts=[m['title'], 'Вымышленный учебный транскрипт. Все участники, организации, показатели и договорённости придуманы.', m['intro']]
    chair, reviewer, proposer, analyst=m['people']
    for i,t in enumerate(m['topics']):
        parts += [f"{chair}: Переходим к вопросу «{t['title']}».",
          f"{t['owner']}: {OPENERS[i%7]} {t['fact']}",
          f"{reviewer}: {QUESTIONS[(i+2)%7]} {t['risk']}",
          f"{proposer}: {OPTIONS[(i+4)%7]} Первый вариант: {t['a']} Второй вариант: {t['b']}",
          f"{analyst}: {CHECKS[(i+1)%7]} Для этого вопроса проверка следующая: {t['check']}",
          f"{chair}: {DECISIONS[(i+5)%7]} Решили: {t['decision']} Ответственный — {t['owner']}. Срок — {t['deadline']}.",
          f"{t['owner']}: {OWNERS[(i+3)%7]} Открытый вопрос, по которому сегодня нет окончательного ответа: {t['open']}"]
    parts.append(m['ending'])
    text='\n\n'.join(parts)+'\n'
    words=len(WORD.findall(text))
    assert 5000<=words<=15000,(m['id'],words)
    return text,words

